261	func (s *Store) Register(id, site string) (Device, bool, error) {
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		if state, ok := s.devices[id]; ok {
265			return cloneDevice(state.device), false, nil
266		}
267		now := s.now().UTC()
268		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
269		if s.wal != nil {
270			if err := s.wal.appendRecord(recRegister, walRegister{
271				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
272			}); err != nil {
273				return Device{}, false, storageUnavailable(err)
274			}
275		}
276		s.devices[id] = &deviceState{
277			device:  device,
278			known:   make(map[string]knownSample),
279			batches: make(map[string]storedBatch),
280			rules:   make(map[string]*ruleState),
281		}
282		return cloneDevice(device), true, nil
283	}
