285	// GetRetention returns the device's retention limit and history counters.
286	func (s *Store) GetRetention(id string) (RetentionStatus, error) {
287		s.mu.RLock()
288		defer s.mu.RUnlock()
289		state, ok := s.devices[id]
290		if !ok {
291			return RetentionStatus{}, ErrDeviceNotFound
292		}
293		return state.retentionStatus(), nil
294	}
