func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
	if raw := strings.TrimSpace(query.Get("status")); raw != "" {
		if raw != alertStatusActive && raw != alertStatusEnded {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
			return
		}
		filter.Status = raw
	}
	if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
		switch raw {
		case "true", "1":
			v := true
			filter.Acknowledged = &v
		case "false", "0":
			v := false
			filter.Acknowledged = &v
		default:
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
			return
		}
	}
	alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
	if errors.Is(err, ErrDeviceNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrRuleNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
}

func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
	alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
	if err != nil || alertID < 1 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
		return
	}
	alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
	if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	if errors.Is(err, ErrStorageUnavailable) {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	writeJSON(w, http.StatusOK, alert)
}

func finiteFloat(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0)
}

func hasBlankKey(values map[string]*float64) bool {
	for key := range values {
		if strings.TrimSpace(key) == "" {
			return true
		}
	}
	return false
}

// metricValues converts decoded metric values to plain floats. Decoding into
// *float64 keeps JSON null distinguishable from a real 0: a null decodes to a
// nil pointer and is rejected here instead of being silently stored as 0.
// Non-finite numbers are rejected as before.
func metricValues(raw map[string]*float64) (map[string]float64, bool) {
	values := make(map[string]float64, len(raw))
	for key, value := range raw {
		if value == nil || !finiteFloat(*value) {
			return nil, false
		}
		values[key] = *value
	}
	return values, true
}

func decodeJSON(r *http.Request, target any) error {
	decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	return decoder.Decode(target)
}

// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
// trailing data such as a second JSON object or concatenated documents.
func decodeSingleJSON(r *http.Request, target any) error {
	decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return errors.New("body must contain a single JSON value")
	}
	return nil
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

package fleet

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
	"time"
)

// pageCursor is the opaque, tamper-evident continuation token used by the
// history endpoint. It pins the device, filter and first-page high-water mark
// so a paged walk cannot see rows written after the first page.
type pageCursor struct {
	DeviceID  string    `json:"d"`
	From      time.Time `json:"f,omitempty"`
	To        time.Time `json:"t,omitempty"`
	HighWater int64     `json:"h"`
	StartSeq  int64     `json:"s"`           // first receive sequence the next page scans
	IID       []byte    `json:"i,omitempty"` // data-directory instance scope
	Version   int       `json:"v,omitempty"` // cursor format version; 0 = legacy index cursor
}

var cursorSecret = []byte("edge-fleet-hub-history-cursor-v1")

// encodeCursor signs the cursor with an HMAC and renders it as base64rawurl.
func encodeCursor(c pageCursor) string {
	c.Version = 2
	payload, _ := json.Marshal(c)
	mac := hmac.New(sha256.New, cursorSecret)
	mac.Write(payload)
	token := append(mac.Sum(nil), payload...)
	return base64.RawURLEncoding.EncodeToString(token)
}

// decodeCursor verifies the signature and parses the cursor. Legacy cursors
// written with index coordinates are translated to sequence coordinates.
func decodeCursor(raw string) (pageCursor, error) {
	token, err := base64.RawURLEncoding.DecodeString(strings.TrimSpace(raw))
	if err != nil || len(token) <= sha256.Size {
		return pageCursor{}, errors.New("invalid cursor")
	}
	signature, payload := token[:sha256.Size], token[sha256.Size:]
	mac := hmac.New(sha256.New, cursorSecret)
	mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return pageCursor{}, errors.New("invalid cursor")
	}
	var cursor pageCursor
	if err := json.Unmarshal(payload, &cursor); err != nil {
		return pageCursor{}, errors.New("invalid cursor")
	}
	switch cursor.Version {
	case 0:
		// Cursors issued before retention used a 0-based array index ("p").
		// Those predate trimming, so event base was 0 and index p maps to
		// sequence p+1.
		var legacy struct {
			DeviceID  string    `json:"d"`
			From      time.Time `json:"f,omitempty"`
			To        time.Time `json:"t,omitempty"`
			HighWater int64     `json:"h"`
			ScanPos   int64     `json:"p"`
			IID       []byte    `json:"i,omitempty"`
		}
		if err := json.Unmarshal(payload, &legacy); err != nil {
			return pageCursor{}, errors.New("invalid cursor")
		}
		if legacy.ScanPos < 0 {
			return pageCursor{}, errors.New("invalid cursor")
		}
		cursor.DeviceID = legacy.DeviceID
		cursor.From = legacy.From
		cursor.To = legacy.To
		cursor.HighWater = legacy.HighWater
		cursor.IID = legacy.IID
		cursor.StartSeq = legacy.ScanPos + 1
	case 2:
		if cursor.StartSeq < 1 {
			return pageCursor{}, errors.New("invalid cursor")
		}
	default:
		return pageCursor{}, errors.New("invalid cursor")
	}
	return cursor, nil
}

package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"github.com/Hulalalalalalalalalalala/edge-fleet-hub/internal/fleet"
)

func main() {
	addr := os.Getenv("EDGE_FLEET_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}

	store := fleet.NewStore()
	persistent := false
	if dataDir := strings.TrimSpace(os.Getenv("EDGE_FLEET_DATA_DIR")); dataDir != "" {
		// Recovery (and inter-process locking) completes before the server
		// accepts any business request. Failure here is fatal; the service
		// never silently falls back to in-memory mode.
		recovered, err := fleet.NewPersistentStore(dataDir)
		if err != nil {
			log.Fatalf("edge fleet hub: opening data directory %s failed: %v", dataDir, err)
		}
		store = recovered
		persistent = true
		defer func() {
			if err := store.Close(); err != nil {
				log.Printf("edge fleet hub: closing data directory failed: %v", err)
			}
		}()
	}

	server := &http.Server{Addr: addr, Handler: fleet.NewHandler(store)}
	if persistent {
		log.Printf("edge fleet hub listening on http://%s (persistent mode, data dir %s)", addr, os.Getenv("EDGE_FLEET_DATA_DIR"))
	} else {
		log.Printf("edge fleet hub listening on http://%s (in-memory mode)", addr)
	}

	shutdown := make(chan os.Signal, 1)
	signal.Notify(shutdown, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-shutdown
		// Let in-flight writes finish (they reach their durable commit point
		// before responding); requests still cut off remain unacknowledged and
		// may be retried after restart.
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.Shutdown(ctx); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Printf("edge fleet hub: shutdown error: %v", err)
		}
	}()

	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatal(err)
	}
}

